[{"order":1,"type":"heading","text":"Page Object Model (POM) Design Pattern & Best Practices in Selenium"},{"order":2,"type":"paragraph","text":"The Page Object Model (POM) is a design pattern popularized in Selenium test automation that creates an object repository for web UI elements. The central idea is to separate test scripts from page-specific UI structure, reducing code duplication and improving test maintenance."},{"order":3,"type":"heading","text":"Core Concepts of POM"},{"order":4,"type":"bullet_point","text":"Page Class: Each web page in the application has a corresponding Page Class that encapsulates the elements and behaviors of that page."},{"order":5,"type":"bullet_point","text":"Test Script: Test cases are kept separate and interact with the UI solely through the methods provided by the Page Classes."},{"order":6,"type":"bullet_point","text":"Object Repository: Locators and interactions are defined in one place, so if a UI element changes, only the page class needs to be updated."},{"order":7,"type":"heading","text":"Implementing a Page Class"},{"order":8,"type":"paragraph","text":"Below is an example of a typical LoginPage class written in Java using Selenium WebDriver and PageFactory."},{"order":9,"type":"code","text":"public class LoginPage {
    WebDriver driver;

    @FindBy(id = "username")
    WebElement usernameField;

    @FindBy(id = "password")
    WebElement passwordField;

    @FindBy(id = "loginButton")
    WebElement loginButton;

    public LoginPage(WebDriver driver) {
        this.driver = driver;
        PageFactory.initElements(driver, this);
    }

    public void enterUsername(String username) {
        usernameField.sendKeys(username);
    }

    public void enterPassword(String password) {
        passwordField.sendKeys(password);
    }

    public void clickLogin() {
        loginButton.click();
    }

    public void loginToApplication(String user, String pass) {
        enterUsername(user);
        enterPassword(pass);
        clickLogin();
    }
}"},{"order":10,"type":"heading","text":"Implementing the Test Script"},{"order":11,"type":"paragraph","text":"The corresponding test class remains clean and focuses entirely on assertion logic and user journeys."},{"order":12,"type":"code","text":"public class LoginTests {
    WebDriver driver;

    @BeforeMethod
    public void setUp() {
        driver = new ChromeDriver();
        driver.get("https://example.com/login");
    }

    @Test
    public void testValidLogin() {
        LoginPage loginPage = new LoginPage(driver);
        loginPage.loginToApplication("standard_user", "secret_password");

        DashboardPage dashboard = new DashboardPage(driver);
        Assert.assertTrue(dashboard.isWelcomeMessageDisplayed());
    }

    @AfterMethod
    public void tearDown() {
        driver.quit();
    }
}"},{"order":13,"type":"heading","text":"Best Practices for POM"},{"order":14,"type":"bullet_point","text":"Never put assertions inside Page Object methods. Page classes should represent actions and states, while test classes handle validations and assertions."},{"order":15,"type":"bullet_point","text":"Return the corresponding Page object from action methods when navigating to a new page (e.g., returning 'new DashboardPage(driver);' after clicking login)."},{"order":16,"type":"bullet_point","text":"Use explicit waits inside page methods rather than Thread.sleep to handle synchronization issues reliably."},{"order":17,"type":"bullet_point","text":"Keep locators private or protected to strictly encapsulate them and prevent test scripts from referencing locators directly."}]
